#!/usr/bin/env bash
# Fails unless two Maven repositories hold byte-identical artifacts.
#
#   .github/same-artifacts.sh <tested-repo> <rebuilt-repo>
#
# The Publish workflow tests one build and uploads from another, because Gradle's publish tasks
# build what they upload. The plugin build is reproducible (see the Jar settings in
# plugin/build.gradle.kts), so the job that uploads publishes to a local repository first and this
# proves it is about to upload exactly what was tested. maven-metadata files are left out: they
# carry a timestamp and are regenerated by every publish anyway.
set -euo pipefail

fail() { echo "FAIL: $*" >&2; exit 1; }
[ $# -eq 2 ] || fail "usage: $0 <tested-repo> <rebuilt-repo>"

sums() { (cd "$1" && find . -type f ! -name 'maven-metadata*' -exec sha256sum {} + | sort -k 2); }

tested="$(sums "$1")" || fail "cannot read $1"
rebuilt="$(sums "$2")" || fail "cannot read $2"
[ -n "$tested" ] || fail "no artifacts in $1"

echo "$tested"
if ! diff <(echo "$tested") <(echo "$rebuilt") >&2; then
  fail "the rebuilt artifacts differ from the tested ones (diff above); refusing to publish what no test ran against"
fi
echo "ok: the rebuilt artifacts are byte-identical to the tested ones"
